-- 翻訳ポリシー:
--   - 静的UIラベル・ボタン文言・ツールチップは翻訳する
--   - PoE固有のゲーム用語（damage type, skill name, item name, modifier等）は
--     ゲーム本体との対応がつくよう原則として英語維持
--   - 統計ラベル末尾の ":" は描画時に付与される版もあるので両方登録する
--
-- 文字列が DrawString に渡る形式:
--   "Total Life:" や "^x70FF70Total Life:" (カラーエスケープ付き)
--   Localization.lua の hook がカラーエスケープを剥がして lookup するため、
--   キーは原則として「カラーエスケープを除いた素の文字列」で登録する

